import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 80 · Christmas recipe: homemade cranberry sauce

sc("""Sweetheart, every Christmas dinner in America has a can of jellied cranberry sauce sliced into little discs, with the ridges from the can still on it. And every year, half of it goes in the trash. Homemade cranberry sauce takes ten minutes, costs about three dollars, and it's so good people eat it with a spoon. But most people make it bitter, runny, or flat.""",
   "canned cranberry sauce slices with ridges", "STRAIGHT FROM THE CAN")
sc("""So tonight I'm giving you my mother's Christmas cranberry sauce, step by step, and the five mistakes that ruin it. And stay with me, because the last secret is one ingredient my mother added at the very end, and it's the reason my Aunt Margaret asked for the recipe every year for forty years and never got it.""",
   "homemade cranberry sauce in glass bowl", "ONE SECRET INGREDIENT")

ch("The bog")
sc("""Cranberries are one of the only fruits that are truly American, honey. The native people of New England were eating them long before the Pilgrims came, and they used them for food, for medicine, and to dye cloth red. The sailors called them crane berries, because the little pink flowers looked like the head of a crane. Over time, it became cranberry.""",
   "cranberry bog harvest flooded red", "CRANE BERRIES")
sc("""The canned sauce came along in nineteen twelve, from a cranberry grower in Massachusetts who didn't want to waste his bruised berries. By the nineteen forties, it was on every table in America. My mother wouldn't touch it. She said, Ruthie, anything that comes out of a can in the shape of a can isn't food. It's a doorstop.""",
   "vintage canned cranberry sauce label", "IT'S A DOORSTOP")
sc("""In our house on Elm Street, the cranberry sauce was always made on Christmas Eve, after supper, in my grandmother's old enamel pot. Danny and I got to listen for the pops. Because when you cook cranberries, honey, they pop, one by one, like tiny firecrackers. In a minute I'll tell you why that pop matters so much.""",
   "enamel pot on old stove Christmas Eve", "LISTEN FOR THE POPS")

sc("""And cranberries were what got a lot of families through the winter in the old days, sweetheart. They keep for months in a cold cellar, and they're full of vitamin C. The whaling ships out of New England carried barrels of them to keep the sailors from getting scurvy. Grandma Pearl kept a crock of them in her cellar all winter, under a damp cloth, and they never spoiled.""",
   "crock of cranberries in old cellar", "THEY KEPT ALL WINTER")
ch("What you need")
sc("""Here's what you need. One twelve-ounce bag of fresh cranberries. One cup of sugar. Half a cup of water and half a cup of fresh orange juice. The zest of one orange. A pinch of salt. And a cinnamon stick if you like it. That's it. You'll have about two and a half cups, enough for ten people, and it keeps for two weeks.""",
   "fresh cranberries sugar orange cinnamon stick", "THE INGREDIENTS")
sc("""And here's mistake number one. Not picking through the berries. Every bag has a few soft, brown, or shriveled ones, and a few little stems. One bad berry makes the whole pot taste bitter and musty. Pour them into a bowl of cold water. The good ones float, and they bounce. Throw out anything soft or dark. It takes two minutes.""",
   "cranberries floating in bowl of water", "PICK THEM OVER")
sc("""Frozen cranberries work just as well, sweetheart. Buy four or five bags in November when they're cheap, and throw them in the freezer. Don't thaw them. Just put them straight in the pot. My mother bought ten bags every Thanksgiving and made cranberry bread all winter.""",
   "bags of cranberries in freezer", "BUY THEM IN NOVEMBER")

sc("""And use a stainless steel or enamel pot, honey, not aluminum or cast iron. Cranberries are very sour, and the acid reacts with bare metal. It turns the sauce a dull brown color and gives it a tinny taste, like licking a spoon. Grandma Pearl's enamel pot was white with a red rim, and it's sitting on my stove right now. I've never made it in anything else.""",
   "white enamel pot with red rim", "THE RIGHT POT")
ch("Cooking it")
sc("""Put the sugar, the water, the orange juice, and the pinch of salt in a pot. Stir it over medium heat until the sugar melts and it comes to a boil. Then add the cranberries and the cinnamon stick. Mistake number two is putting the berries and the sugar in cold water together. Melt the sugar first, so the berries cook in syrup and stay bright and glossy.""",
   "sugar syrup boiling in pot", "SYRUP FIRST")
sc("""Now listen. In about four minutes, they start to pop. Pop, pop, pop. That's the skins bursting and letting out the pectin, which is what makes the sauce thicken. Let them cook at a gentle boil for about ten minutes, until most have popped. And here's mistake number three. Cooking it too long. Twenty minutes, and it turns into thick, dark, bitter jam.""",
   "cranberries popping in pot", "POP, POP, POP")
sc("""If this is helping you, tap the like button for me, honey. It helps Grandma more than you know. And mistake number four. Taking it off the heat because it looks too runny. It's supposed to look runny when it's hot. As it cools, the pectin sets it, and it gets twice as thick. If it's thick in the pot, it'll be cement on the table.""",
   "runny hot cranberry sauce in pot", "RUNNY IS RIGHT")

sc("""Here's how to know when it's ready, sweetheart. Dip a cold metal spoon into the pot and lift it out. If the sauce coats the back of the spoon and slides off slowly, in a sheet, it's done. If it runs off like water, give it two more minutes. Then turn off the heat. It's the same test my mother used for jelly, and it never fails.""",
   "sauce coating back of metal spoon", "THE SPOON TEST")
ch("The secret")
sc("""Now the secret I promised you. Take it off the heat, pull out the cinnamon stick, and stir in the orange zest. And then my mother's secret. One tablespoon of butter and a splash of vanilla. The butter makes it glossy and smooth and takes away that sharp edge, and the vanilla makes it taste rich and round, like a dessert.""",
   "stirring butter into cranberry sauce", "BUTTER AND VANILLA")
sc("""Aunt Margaret asked my mother every Christmas, Dorothy, what do you put in it? And my mother always said, love, Margaret. Just love. I didn't find out myself until I was thirty, when I watched my mother sneak that butter in while Aunt Margaret was in the other room. Aunt Margaret died not knowing. And now you know, sweetheart.""",
   "two women in Christmas kitchen 1970s", "JUST LOVE")

sc("""And for a pretty table, here's my mother's mold trick. Lightly oil a small bundt pan or a pretty glass bowl, pour in the hot sauce, and chill it overnight. On Christmas Day, dip the bottom in warm water for ten seconds and turn it out onto a plate. It comes out in a shiny ruby ring. Put a little sprig of rosemary in the middle. People will gasp.""",
   "cranberry sauce molded ring on plate", "A RUBY RING")
ch("Serving it")
sc("""Mistake number five. Serving it hot. Cranberry sauce is best cold, or at room temperature. Make it at least one day ahead, put it in a glass bowl, cover it, and keep it in the icebox. It thickens and the flavor gets deeper overnight. On Christmas Day, all you have to do is take the cover off.""",
   "cranberry sauce in glass bowl icebox", "MAKE IT A DAY AHEAD")
sc("""And use the leftovers, honey. Spread it on a turkey sandwich with cream cheese the next day. Stir it into oatmeal or plain yogurt. Spoon it over a block of cream cheese with crackers for an easy party snack. Or mix it with a little mustard for a glaze on ham. My husband put it on his pancakes on December twenty-sixth, every single year.""",
   "turkey cranberry sandwich cream cheese", "THE LEFTOVERS")

ch("Making it your own")
sc("""Once you know how, change it any way you like. Add a handful of chopped pecans or walnuts at the end for crunch. Add a chopped apple or pear with the berries for a softer, sweeter sauce. A splash of port wine or bourbon for the grown-ups. Or a little grated fresh ginger, which my granddaughter loves. It's hard to ruin, sweetheart, once you know the rules.""",
   "cranberry sauce with pecans and pear", "MAKE IT YOUR OWN")
sc("""And here's my favorite way to give it as a gift. Make a double batch, pour it into little jelly jars while it's hot, put on the lids, and tie a red ribbon around each one with a little tag. It keeps two weeks in the icebox. I give one to every neighbor on our street, and they think I'm the fanciest cook in Ohio. It costs about a dollar a jar.""",
   "jars of cranberry sauce with red ribbons", "A DOLLAR A JAR")

sc("""One more idea for Christmas morning, honey. Stir a big spoonful of the sauce into your pancake or muffin batter, or swirl it into a coffee cake before baking. Little red streaks all through it, and it tastes like Christmas. I make cranberry orange muffins every Christmas morning with the leftovers, and my grandchildren think I bought them at a bakery.""",
   "cranberry orange muffins Christmas morning", "CHRISTMAS MORNING MUFFINS")
ch("Grandma's kitchen")
sc("""So one more time. Pick over your berries in cold water. Melt the sugar first. Cook it just until the berries pop, about ten minutes. Don't worry if it looks runny. Stir in the orange zest, the butter, and the vanilla. And make it a day ahead. That's cranberry sauce your family will eat with a spoon, and nobody will ever buy the can again.""",
   "Christmas dinner table with cranberry sauce", "NEVER THE CAN AGAIN")
sc("""Tell me in the comments, sweetheart. Are you a can person or a homemade person? Be honest with Grandma. The whole playlist of Grandma's recipes is right there on your screen, and I'll see you in the next video. Good night, honey. Merry Christmas.""",
   "Christmas kitchen evening candles", "CAN OR HOMEMADE?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma80", "Cranberry Sauce EVERYONE's Grandma Made (Why Yours Is BITTER)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "Cranberries are native to North America; canned cranberry sauce was introduced in 1912 by a Massachusetts grower (later Ocean Spray).",
      "Recipe as written by Grandma Ruth: 12 oz cranberries, 1 cup sugar, 1/2 cup water, 1/2 cup orange juice, orange zest, pinch of salt, cinnamon stick; about 10 minutes at a gentle boil; finished with 1 tbsp butter and a splash of vanilla."],
     "christmas recipe", minutes=(10, 14.5), voice="en_US-lessac-high")
